53:.phases{list-style:none;padding:0;gap:1rem;counter-reset:ph}
54:.phase{background:var(--paper);border:1px solid var(--rule);border-radius:6px;padding:1rem 1.1rem;display:grid;gap:.6rem;counter-increment:ph}
55:.phase h3::before{content:"Phase " counter(ph) " · ";color:var(--accent);font-family:"IBM Plex Mono",ui-monospace,monospace;font-size:.82rem;font-weight:500;letter-spacing:.02em}
58:.asks{counter-reset:ask;list-style:none;padding:0;gap:.7rem}
59:.asks > li{counter-increment:ask;display:grid;grid-template-columns:2.1rem 1fr;gap:.2rem .5rem}
60:.asks > li::before{content:counter(ask);font:500 .85rem/1.9 "IBM Plex Mono",ui-monospace,monospace;color:var(--you);text-align:right;padding-right:.2rem}
62:.asks > li.group{counter-increment:none;display:block}
